LuaFunction.Formula:
function _JBTEH_KTL_chkRelations() local _rWtb, nWtb = getRelatedObjects(rel_ContactWireOrMidpointAnchoringLineOrHvConductor_IsTensionedBy_Wtb) local _rCnt, nCnt = getRelatedObjects(rel_ContactWire_IsHeldBy_Cantilever) local _rMap, nMap = getRelatedObjects(rel_ContactWire_IsLockedBy_MidpointAnchor)
--Regular CW: if Variant == "Contact Wire from tension balancer to tension balancer" then if nWtb == 0 then if nCnt > 0 then if nMap == 0 or nMap == 1 then return _ok,"OK - Regular CW is related to at least one cantilever, to zero or one midpoint anchor, no WTB." else return _error,"ERROR - Regular CW has too many midpoint anchors." end else return _unfinished,"UNFINISHED - Regular CW shall relate to at least one cantilever." end else return _error,"ERROR - Regular CW shall not relate to a WTB." end
else return _error,"ERROR - Bad variant '"..Variant.."'." end end

function _JBTEH_KTL_getOtherObjectsToModelcheck()
	local t = getNearbyPointObjects2D(0.10)
	local n = t.Count
	return n, t, _info(n.." objects close to this contact wire have been modelchecked.")
end
